sed -i 's/is SpeechState.Idle/is SpeechState.Ready/g' app/src/main/java/com/example/ui/JarvisViewModel.kt
sed -i 's/is SpeechState.Error -> {/is SpeechState.Error -> { \n                        _uiState.value = _uiState.value.copy( \n                            isListening = false, \n                            status = "Error: ${state.message}" \n                        ) \n                    } \n                    is SpeechState.PermissionRequired -> { \n                        _uiState.value = _uiState.value.copy( \n                            isListening = false, \n                            status = "Microphone permission required" \n                        ) \n                    } \n                    is SpeechState.Unavailable -> { \n                        _uiState.value = _uiState.value.copy( \n                            isListening = false, \n                            status = "Speech recognition unavailable" \n                        ) \n                    } \n                    is SpeechState.Processing -> { \n                        _uiState.value = _uiState.value.copy( \n                            isListening = false, \n                            status = "Processing speech..." \n                        ) \n                    }/g' app/src/main/java/com/example/ui/JarvisViewModel.kt
sed -i 's/status = "Error: ${state.error}"//g' app/src/main/java/com/example/ui/JarvisViewModel.kt
